[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$WorkspacePath,[Parameter(Mandatory=$true)][string]$ProductRoot)
$ErrorActionPreference='Stop';$binding=Get-Content (Join-Path $WorkspacePath 'governance\policies\release-binding.json') -Raw|ConvertFrom-Json;if([string]$binding.repository_url -ne 'https://github.com/sivla/BCProjectOS.git'){throw 'CONSUMER_REPOSITORY_NOT_CANONICAL'};if([string]$binding.binding_status -ne 'BOUND'){throw 'CONSUMER_BINDING_NOT_BOUND'};foreach($p in @('release_version','release_tag','tag_commit','manifest_path','manifest_source_commit','consumer_mode','payload_bundle_digest')){if([string]::IsNullOrWhiteSpace([string]$binding.$p)){throw "CONSUMER_BINDING_FIELD_MISSING:$p"}};if([string]$binding.manifest_path -match '^[A-Za-z]:|\.\.|\\'){throw 'CONSUMER_MANIFEST_PATH_UNSAFE'};& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'Test-CustomerWorkspace.ps1') -Path $WorkspacePath -ProductRoot $ProductRoot;if($LASTEXITCODE -ne 0){throw 'CONSUMER_WORKSPACE_VALIDATION_FAILED'};Write-Host 'PASS: Portable consumer workspace validation is read-only and release-bound.'
